def _build_dataprovider_method(method, dataset, dataprovider):
    """
    Constructs a new test method by wrapping the given method with the specified dataset and dataprovider.

    This function returns a fabricated method that calls the dataprovider with the given dataset, and marshals the return value from that into parameters for the underlying test 'method'. The purpose is to dynamically generate test cases using the provided dataprovider function.

    :param method: The underlying test method to call.
    :type method: callable
    :param dataset: Tuple or GentyArgs instance containing the arguments of the dataset.
    :type dataset: tuple or :class:`GentyArgs`
    :param dataprovider: The unbound function responsible for generating the actual parameters that will be passed to the test method.
    :type dataprovider: callable
    :return: A new test method that incorporates the dataset and dataprovider.
    :rtype: callable

    Example usage:
    def test_example(self, param1, param2):
        # Test logic here

    def dataprovider_function(self, arg1, arg2):
        # Generate test data
        return (arg1 + 1, arg2 + 2)

    dataset = (1, 2)
    wrapped_method = _build_dataprovider_method(test_example, dataset, dataprovider_function)
    """
    if isinstance(dataset, GentyArgs):
        final_args = dataset.args
        final_kwargs = dataset.kwargs
    else:
        final_args = dataset
        final_kwargs = {}

    def test_method_wrapper(my_self):
        args = dataprovider(
            my_self,
            *final_args,
            **final_kwargs
        )

        kwargs = {}

        if isinstance(args, GentyArgs):
            kwargs = args.kwargs
            args = args.args
        elif not isinstance(args, (tuple, list)):
            args = (args, )

        return method(my_self, *args, **kwargs)

    return test_method_wrapper
