import pytest
from genty.genty_args import genty_args, GentyArgs

def test_genty_args_no_args():
    result = genty_args()
    assert result.args == ()
    assert result.kwargs == {}

def test_genty_args_positional_only():
    result = genty_args(1, 2, 3)
    assert result.args == (1, 2, 3)
    assert result.kwargs == {}

def test_genty_args_keyword_only():
    result = genty_args(a=1, b=2, c=3)
    assert result.args == ()
    assert result.kwargs == {'a': 1, 'b': 2, 'c': 3}

def test_genty_args_mixed_positional_and_keyword():
    result = genty_args(1, 2, a=3, b=4)
    assert result.args == (1, 2)
    assert result.kwargs == {'a': 3, 'b': 4}

def test_genty_args_with_default_arguments():
    result = genty_args('hello', world=True)
    assert result.args == ('hello',)
    assert result.kwargs == {'world': True}

def test_genty_args_multiple_keyword_arguments():
    result = genty_args(x=10, y=20, z=30)
    assert result.args == ()
    assert result.kwargs == {'x': 10, 'y': 20, 'z': 30}

